commits.content:
body {
    background-color: #040D12;
    color: black;
    font-family: 'Inter', sans-serif;
    font-size: medium;
    margin: 0;
    padding: 0;
}

.wrapper {
    display: block;
    width: 648px;
    margin: 0 auto; 
    padding-top: 20px;
}

#cover {
    background-position: center;
    height: 50vh;
    background-image: url('img/head.jpg');
    background-size: cover;
    width: 100%;
}

header {
    margin-top: 20px;
    text-align: center;
}

.navbar{
    display: flex;
    justify-content: space-between;
    align-items: center;
    /* border-bottom: 1px solid #ccc; */
    padding: 10px 0;
}

.title {
    font-size: 2.25rem;
    font-family: 'Inter';
    margin: 1rem;
    padding-left: 1rem;
    text-transform: uppercase;
}

.navbar{
    justify-content: space-between;
    align-items: center;
    text-align: center;
    padding: 10px 0;
}

.navbar-links ul {
    margin: 0;
    padding: 0;
    display: flex;
}

.navbar-links li{
    list-style: none;
    border-radius: 10px;
    padding: 1rem;
    display: block;
    font-style: bold;
    font-size: 1rem;
}

a {
    text-decoration: none;
    color: white;
}

section {
    padding-top: 10px;
}

